# Generated by build.py from recipe.yml for recipe sftp-offer-weak-algorithms-for-old-clients. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site old
printf '%s\n' 'hello from surl' > site/hello.txt
printf '%s\n' 'hello from an old surl' > old/hello.txt
printf '%s\n' 'get hello.txt got.txt' > get.sftp
ssh-keygen -t rsa -b 3072 -N "" -f host_key
ssh-keygen -t rsa -b 1024 -N "" -f old_key
ssh-keygen -t ed25519 -N "" -f client_key
surl --allow-weak-ssh-algorithms --directory site --hostkey host_key --authorized-keys alice:client_key.pub sftp://127.0.0.1:8081/ &
sleep 1
sftp -q -b get.sftp -P 8081 -i client_key -o Ciphers=aes128-cbc -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o GlobalKnownHostsFile=/dev/null alice@127.0.0.1
kill $(jobs -p)
